insert into questions(category,version,ord,value,type,q,a,note,flag,clues,num,evidence,suspects) values
('rescue',2,2,400,'normal','إذا كان الكأس يعود لسالم فعلاً، كيف يمكن للمحامي التشكيك في دلالته الجنائية؟','بأن سالم زار المكتب في وقت سابق وليس وقت الجريمة "الدليل الظرفي','اتُهم (سالم) بقتل رجل أعمال في مكتبه الساعة 10 مساءً. الدليل الوحيد هو بصمة سالم على "كأس زجاجي" بجانب الجثة. سالم يصر أنه كان في مطعم يبعد 20 كم عن مسرح الجريمة في ذلك الوقت، لكن لا يوجد شهود، والمطعم لا يحتوي على كاميرات مراقبة.',NULL,NULL,NULL,NULL,NULL),
('rescue',2,3,400,'normal','ماذا يسمى دفع المحامي بأن المتهم كان في مكان آخر وقت وقوع الجريمة؟','دفع "حجة الغياب" أو Alibi','اتُهم (سالم) بقتل رجل أعمال في مكتبه الساعة 10 مساءً. الدليل الوحيد هو بصمة سالم على "كأس زجاجي" بجانب الجثة. سالم يصر أنه كان في مطعم يبعد 20 كم عن مسرح الجريمة في ذلك الوقت، لكن لا يوجد شهود، والمطعم لا يحتوي على كاميرات مراقبة.',NULL,NULL,NULL,NULL,NULL),
('rescue',2,4,600,'normal','كيف يمكن تقنياً استخدام "سجل المكالمات والبيانات" للهاتف لإثبات براءة سالم؟','تحليل البيانات الجغرافية للأبراج التي التقطت إشارة هاتفه في المنطقة البعيدة وقت وقوع الجريمة','اتُهم (سالم) بقتل رجل أعمال في مكتبه الساعة 10 مساءً. الدليل الوحيد هو بصمة سالم على "كأس زجاجي" بجانب الجثة. سالم يصر أنه كان في مطعم يبعد 20 كم عن مسرح الجريمة في ذلك الوقت، لكن لا يوجد شهود، والمطعم لا يحتوي على كاميرات مراقبة.',NULL,NULL,NULL,NULL,NULL),
('rescue',2,5,600,'normal','إذا اكتشف المحامي أن الكأس نُقل من مكان آخر للمكتب، ما هو المصطلح القانوني للتلاعب بالأدلة؟','تلفيق الأدلة أو تضليل العدالة، وهو ما يفسد القضية بالكامل','اتُهم (سالم) بقتل رجل أعمال في مكتبه الساعة 10 مساءً. الدليل الوحيد هو بصمة سالم على "كأس زجاجي" بجانب الجثة. سالم يصر أنه كان في مطعم يبعد 20 كم عن مسرح الجريمة في ذلك الوقت، لكن لا يوجد شهود، والمطعم لا يحتوي على كاميرات مراقبة.',NULL,NULL,NULL,NULL,NULL),
('crime',3,0,200,'normal','لماذا يعتبر تسجيل الدخول الإلكتروني دليلاً حاسماً؟','لأنه يحدد هوية حامل المفتاح في لحظة الدخول','في ليلة ضبابية، اختفت وثيقة سرية من خزانة مكتب المحامي (عادل). المكتب يقع في الدور العاشر. لا توجد آثار اقتحام للنوافذ، وباب المكتب لا يفتح إلا بمفتاح إلكتروني سجل دخوله في وقت الجريمة. المشتبه بهم هم: السكرتيرة، شريك عادل، وعامل التنظيف. وُجدت بقعة قهوة على مكتب عادل، ورائحة سجائر (رغم أن عادل لا يدخن).',NULL,NULL,NULL,NULL,NULL),
('crime',3,1,200,'normal','ما هي أهمية بقعة القهوة في مسرح الجريمة؟','قد تحتوي على بصمات أو تدل على توقيت الجريمة بناءً على جفافها','في ليلة ضبابية، اختفت وثيقة سرية من خزانة مكتب المحامي (عادل). المكتب يقع في الدور العاشر. لا توجد آثار اقتحام للنوافذ، وباب المكتب لا يفتح إلا بمفتاح إلكتروني سجل دخوله في وقت الجريمة. المشتبه بهم هم: السكرتيرة، شريك عادل، وعامل التنظيف. وُجدت بقعة قهوة على مكتب عادل، ورائحة سجائر (رغم أن عادل لا يدخن).',NULL,NULL,NULL,NULL,NULL),
('crime',3,2,400,'normal','إذا كان عادل لا يدخن، ماذا تعني رائحة السجائر؟','دليل مادي على وجود شخص آخر في المكان','في ليلة ضبابية، اختفت وثيقة سرية من خزانة مكتب المحامي (عادل). المكتب يقع في الدور العاشر. لا توجد آثار اقتحام للنوافذ، وباب المكتب لا يفتح إلا بمفتاح إلكتروني سجل دخوله في وقت الجريمة. المشتبه بهم هم: السكرتيرة، شريك عادل، وعامل التنظيف. وُجدت بقعة قهوة على مكتب عادل، ورائحة سجائر (رغم أن عادل لا يدخن).',NULL,NULL,NULL,NULL,NULL),
('crime',3,3,400,'normal','كيف يفسر غياب آثار اقتحام النوافذ؟','السارق كان يمتلك مفتاحاً أو كان ضيفاً دخل بإذن','في ليلة ضبابية، اختفت وثيقة سرية من خزانة مكتب المحامي (عادل). المكتب يقع في الدور العاشر. لا توجد آثار اقتحام للنوافذ، وباب المكتب لا يفتح إلا بمفتاح إلكتروني سجل دخوله في وقت الجريمة. المشتبه بهم هم: السكرتيرة، شريك عادل، وعامل التنظيف. وُجدت بقعة قهوة على مكتب عادل، ورائحة سجائر (رغم أن عادل لا يدخن).',NULL,NULL,NULL,NULL,NULL),
('crime',3,4,600,'normal','كيف يمكن كشف السارق من بين الثلاثة باستخدام سجلات الدخول؟','مقارنة أوقات تسجيل الدخول مع كاميرات المراقبة بالممر للتحقق من هوية الشخص الذي دخل','في ليلة ضبابية، اختفت وثيقة سرية من خزانة مكتب المحامي (عادل). المكتب يقع في الدور العاشر. لا توجد آثار اقتحام للنوافذ، وباب المكتب لا يفتح إلا بمفتاح إلكتروني سجل دخوله في وقت الجريمة. المشتبه بهم هم: السكرتيرة، شريك عادل، وعامل التنظيف. وُجدت بقعة قهوة على مكتب عادل، ورائحة سجائر (رغم أن عادل لا يدخن).',NULL,NULL,NULL,NULL,NULL),
('crime',3,5,600,'normal','إذا وُجدت بصمة سكرتيرة عادل على فنجان القهوة، هل هي سارقة؟','ليس بالضرورة، قد تكون قدمت القهوة، المحقق يجب أن يبحث عن دليل ربط بين البصمة والوثيقة المختفية','في ليلة ضبابية، اختفت وثيقة سرية من خزانة مكتب المحامي (عادل). المكتب يقع في الدور العاشر. لا توجد آثار اقتحام للنوافذ، وباب المكتب لا يفتح إلا بمفتاح إلكتروني سجل دخوله في وقت الجريمة. المشتبه بهم هم: السكرتيرة، شريك عادل، وعامل التنظيف. وُجدت بقعة قهوة على مكتب عادل، ورائحة سجائر (رغم أن عادل لا يدخن).',NULL,NULL,NULL,NULL,NULL),
('rescue',3,0,200,'normal','ما هو اسم الخبير الذي يفحص الخط والتواقيع؟','خبير الخطوط والمستندات','اتُهم (خالد) بتزوير مستندات شركة. الدليل هو توقيعه الموجود على العقد. خالد يدعي أن توقيعه "مقلد" وأن العقد تم توقيعه في يوم كان هو فيه في سفر خارج البلاد.',NULL,NULL,NULL,NULL,NULL),
('rescue',3,1,200,'normal','ما هي الوثيقة التي تثبت سفر خالد؟','ختم جواز السفر أو سجلات شركة الطيران','اتُهم (خالد) بتزوير مستندات شركة. الدليل هو توقيعه الموجود على العقد. خالد يدعي أن توقيعه "مقلد" وأن العقد تم توقيعه في يوم كان هو فيه في سفر خارج البلاد.',NULL,NULL,NULL,NULL,NULL),
('rescue',3,2,400,'normal','كيف يمكن كشف التزوير في التوقيع؟','عن طريق فحص ضغط القلم، اتجاه الخط، وتطابق أسلوب التوقيع مع التواقيع الأصلية','اتُهم (خالد) بتزوير مستندات شركة. الدليل هو توقيعه الموجود على العقد. خالد يدعي أن توقيعه "مقلد" وأن العقد تم توقيعه في يوم كان هو فيه في سفر خارج البلاد.',NULL,NULL,NULL,NULL,NULL),
('rescue',3,3,400,'normal','ما هو الدفع القانوني الذي يقدمه المحامي بخصوص المستند؟','الدفع بالطعن بالتزوير','اتُهم (خالد) بتزوير مستندات شركة. الدليل هو توقيعه الموجود على العقد. خالد يدعي أن توقيعه "مقلد" وأن العقد تم توقيعه في يوم كان هو فيه في سفر خارج البلاد.',NULL,NULL,NULL,NULL,NULL),
('rescue',3,4,600,'normal','ماذا لو كانت كاميرات الشركة سجلت شخصاً يشبه خالد؟','يطلب المحامي تفريغ الكاميرات بدقة عالية وطلب تحليل "التعرف على الوجوه','اتُهم (خالد) بتزوير مستندات شركة. الدليل هو توقيعه الموجود على العقد. خالد يدعي أن توقيعه "مقلد" وأن العقد تم توقيعه في يوم كان هو فيه في سفر خارج البلاد.',NULL,NULL,NULL,NULL,NULL),
('rescue',3,5,600,'normal','إذا أثبتت التحاليل أن الحبر المستخدم في العقد جديد بينما العقد تاريخه قديم، ماذا يعني ذلك؟','دليل قاطع على التزوير الحديث','اتُهم (خالد) بتزوير مستندات شركة. الدليل هو توقيعه الموجود على العقد. خالد يدعي أن توقيعه "مقلد" وأن العقد تم توقيعه في يوم كان هو فيه في سفر خارج البلاد.',NULL,NULL,NULL,NULL,NULL),
('crime',4,0,200,'normal','لماذا يعتبر عدم تفعيل أجهزة الليزر دليلاً قوياً على تورط شخص من الداخل؟','لأنها تدل على معرفة مسبقة بكلمة السر أو مفتاح النظام','في مخزن أدوية، سُرقت كمية كبيرة من العقاقير المخدرة. الكاميرات تُظهر شخصاً يرتدي قناعاً يدخل في الساعة 3 صباحاً. أجهزة الاستشعار (الليزر) لم تُفعل، مما يعني أن السارق كان يمتلك رمز التعطيل. المشتبه بهم هم: مدير المخزن، صيدلي، وحارس ليلي. وُجدت آثار مادة كيميائية (مذيب دهانات) على باب المخزن.',NULL,NULL,NULL,NULL,NULL),
('crime',4,1,200,'normal','لماذا يتم رفع البصمات من مقابض الأبواب قبل أي شيء؟','لأنها المكان الأكثر عرضة للمس','في مخزن أدوية، سُرقت كمية كبيرة من العقاقير المخدرة. الكاميرات تُظهر شخصاً يرتدي قناعاً يدخل في الساعة 3 صباحاً. أجهزة الاستشعار (الليزر) لم تُفعل، مما يعني أن السارق كان يمتلك رمز التعطيل. المشتبه بهم هم: مدير المخزن، صيدلي، وحارس ليلي. وُجدت آثار مادة كيميائية (مذيب دهانات) على باب المخزن.',NULL,NULL,NULL,NULL,NULL),
('crime',4,2,400,'normal','ماذا يعني وجود "مذيب دهانات" على باب المخزن؟','قد يعني أن السارق حاول مسح بصماته أو تخريب النظام الإلكتروني','في مخزن أدوية، سُرقت كمية كبيرة من العقاقير المخدرة. الكاميرات تُظهر شخصاً يرتدي قناعاً يدخل في الساعة 3 صباحاً. أجهزة الاستشعار (الليزر) لم تُفعل، مما يعني أن السارق كان يمتلك رمز التعطيل. المشتبه بهم هم: مدير المخزن، صيدلي، وحارس ليلي. وُجدت آثار مادة كيميائية (مذيب دهانات) على باب المخزن.',NULL,NULL,NULL,NULL,NULL),
('crime',4,3,400,'normal','ما هو الفرق بين "الدليل المادي" و"الدليل الظرفي" في هذه القضية؟','الدليل المادي كبصمة الإصبع، والظرفي كتواجد الحارس في موقع الجريمة','في مخزن أدوية، سُرقت كمية كبيرة من العقاقير المخدرة. الكاميرات تُظهر شخصاً يرتدي قناعاً يدخل في الساعة 3 صباحاً. أجهزة الاستشعار (الليزر) لم تُفعل، مما يعني أن السارق كان يمتلك رمز التعطيل. المشتبه بهم هم: مدير المخزن، صيدلي، وحارس ليلي. وُجدت آثار مادة كيميائية (مذيب دهانات) على باب المخزن.',NULL,NULL,NULL,NULL,NULL),
('crime',4,4,600,'normal','لو وجدنا أن رمز التعطيل تم استخدامه من جهاز المدير، كيف نتحقق من براءته؟','فحص سجلات "التوقيت الفعلي" للجهاز ومقارنته بموقع هاتفه عبر الـ GPS','في مخزن أدوية، سُرقت كمية كبيرة من العقاقير المخدرة. الكاميرات تُظهر شخصاً يرتدي قناعاً يدخل في الساعة 3 صباحاً. أجهزة الاستشعار (الليزر) لم تُفعل، مما يعني أن السارق كان يمتلك رمز التعطيل. المشتبه بهم هم: مدير المخزن، صيدلي، وحارس ليلي. وُجدت آثار مادة كيميائية (مذيب دهانات) على باب المخزن.',NULL,NULL,NULL,NULL,NULL),
('crime',4,5,600,'normal','كيف يمكن لمادة مذيب الدهانات أن تكشف السارق؟','مقارنة نوع المذيب بالمواد الموجودة في ورشة العمل أو سيارة أحد المشتبه بهم','في مخزن أدوية، سُرقت كمية كبيرة من العقاقير المخدرة. الكاميرات تُظهر شخصاً يرتدي قناعاً يدخل في الساعة 3 صباحاً. أجهزة الاستشعار (الليزر) لم تُفعل، مما يعني أن السارق كان يمتلك رمز التعطيل. المشتبه بهم هم: مدير المخزن، صيدلي، وحارس ليلي. وُجدت آثار مادة كيميائية (مذيب دهانات) على باب المخزن.',NULL,NULL,NULL,NULL,NULL),
('rescue',4,0,200,'normal','ما هو المبدأ الذي يمنع الحكم على المتهم بناءً على أدلة غير مباشرة؟','مبدأ الشك يفسر لصالح المتهم','اتُهم (أحمد) بجريمة إلكترونية (اختراق حسابات عملاء). الدليل هو وجود IP خاص بجهازه في وقت العملية. أحمد يدعي أن شبكة الواي فاي الخاصة به "مفتوحة" وأن أحداً من الجيران ربما استخدمها.',NULL,NULL,NULL,NULL,NULL),
('rescue',4,1,200,'normal','ماذا يسمى دور المحامي في طلب فحص الأجهزة؟','طلب خبرة فنية','اتُهم (أحمد) بجريمة إلكترونية (اختراق حسابات عملاء). الدليل هو وجود IP خاص بجهازه في وقت العملية. أحمد يدعي أن شبكة الواي فاي الخاصة به "مفتوحة" وأن أحداً من الجيران ربما استخدمها.',NULL,NULL,NULL,NULL,NULL),
('rescue',4,2,400,'normal','كيف يمكن للمحامي الرد على دليل الـ IP؟','إثبات وجود عدة أجهزة متصلة بالشبكة وقت وقوع الجريمة','اتُهم (أحمد) بجريمة إلكترونية (اختراق حسابات عملاء). الدليل هو وجود IP خاص بجهازه في وقت العملية. أحمد يدعي أن شبكة الواي فاي الخاصة به "مفتوحة" وأن أحداً من الجيران ربما استخدمها.',NULL,NULL,NULL,NULL,NULL),
('rescue',4,3,400,'normal','ما هو "سجل الدخول" الذي يطلبه الخبير التقني؟  للنظام','Log Files','اتُهم (أحمد) بجريمة إلكترونية (اختراق حسابات عملاء). الدليل هو وجود IP خاص بجهازه في وقت العملية. أحمد يدعي أن شبكة الواي فاي الخاصة به "مفتوحة" وأن أحداً من الجيران ربما استخدمها.',NULL,NULL,NULL,NULL,NULL),
